import { useState } from 'react';

const kosong = { nama: '', kota: 'Bandung', kodePos: '', simpan: false };

export default function App() {
  const [form, setForm] = useState(kosong);

  function handleChange(e) {
    const { name, type, value, checked } = e.target;
    setForm({ ...form, [name]: type === 'checkbox' ? checked : value });
  }

  return (
    <form onSubmit={(e) => e.preventDefault()}>
      <p><input name="nama" value={form.nama} onChange={handleChange} placeholder="Nama" /></p>
      <p>
        <select name="kota" value={form.kota} onChange={handleChange}>
          <option>Bandung</option>
          <option>Jakarta</option>
          <option>Surabaya</option>
        </select>
      </p>
      <p><input name="kodePos" value={form.kodePos} onChange={handleChange} placeholder="Kode pos" /></p>
      <label>
        <input type="checkbox" name="simpan" checked={form.simpan} onChange={handleChange} />
        {' '}Simpan alamat
      </label>{' '}
      <button type="button" onClick={() => setForm(kosong)}>Kosongkan</button>
      <pre>{JSON.stringify(form, null, 2)}</pre>
    </form>
  );
}
